const initial={company:{name:'Acme Partners',website:'https://acme.partners',industry:'Technology',region:'North America'},user:{name:'Alex Morgan',email:'alex@acme.partners'},crm:{name:'Salesforce',connected:false,lastSync:'Never synced'},settings:{mfa:true,alerts:true},activity:[]};
let state,hadSavedState=false;try{const saved=localStorage.getItem('minute-v1');state=saved?JSON.parse(saved):structuredClone(initial);hadSavedState=Boolean(saved)}catch{state=structuredClone(initial)}
state.company={...initial.company,...state.company};state.user={...initial.user,...state.user};state.settings={...initial.settings,...state.settings};state.activity=state.activity||[];
// Each sign-in starts at the Salesforce step: Connect Salesforce, or Connect later.
state.crm={name:'Salesforce',connected:false,lastSync:state.crm?.lastSync||'Never synced'};
state.crmSkipped=false;state.signedIn=false;state.setupStep=0;state.onboarding=0;state.agreementAccepted=false;
let connectionPending=false,page='dashboard',toastTimer,lastToastAt=0,welcomeRole=null,reviewTimer=0,cardFlow=null,flashId=null;
// manager.html sends signed-out visitors to the shared sign-in with #manager.
if(location.hash==='#manager')welcomeRole='manager';
// Automatic review: the vendor's decision arrives a few seconds after a submission, with a loading state meanwhile.
const reviewJob=crmId=>state.sales?.crm?.reviewMode==='auto'&&!!crmId&&state.sales.crm.jobs.some(j=>j.crmId===crmId);
function reviewPending(){const crm=state.sales?.crm;if(!crm||!crm.jobs)return false;return crm.jobs.some(j=>(crm.reviewMode==='auto'||crm.registrations[j.crmId]?.registration==='Submitted')&&(crm.leads[j.crmId]||crm.registrations[j.crmId])?.partnerId===state.sales.partnerId);}
function scheduleReview(){if(reviewTimer||!state.signedIn||state.onboarding!==3||!state.crm.connected||!reviewPending())return;reviewTimer=setTimeout(()=>{reviewTimer=0;if(state.signedIn&&state.onboarding===3)startSalesSync();},2600);}
const pages={dashboard:'Overview',leads:'My Leads',assigned:'Assigned Leads',deals:'Deal Registrations',opportunities:'CRM Opportunities',crm:'Salesforce updates',program:'My program',security:'Account & security'};
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const leadCompactMoney=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(v);
const initials=n=>String(n||'Partner').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
function save(){localStorage.setItem('minute-v1',JSON.stringify(state))}
function log(title,detail){state.activity.unshift({title,detail,time:new Date().toISOString()});state.activity=state.activity.slice(0,15);save()}
function toast(message){lastToastAt=Date.now();clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),5000)}
SalesWorkflow.initialize(state,{migrate:hadSavedState});
if(typeof performance!=='undefined'&&performance.getEntriesByType?.('navigation')[0]?.type==='reload')SalesWorkflow.resetSamples(state);
const connectWorkflow=()=>SalesWorkflow.create(state,{save,authorized:()=>state.signedIn&&state.onboarding===3,isOnline:()=>typeof navigator==='undefined'||navigator.onLine!==false});
let workflow=connectWorkflow(),seenManagerRev=state.sales.crm.managerRev||0;
function go(p){if(p==='team')p='program';if(!pages[p])p='dashboard';page=p;if(p==='leads')leadScope='partner';salesQuery='';salesFilter='All statuses';closeModal();render();window.scrollTo(0,0)}
function navButton(id,label){const active=page===id||(id==='leads'&&page==='assigned');return `<button data-page="${id}" title="${esc(label)}" aria-label="${esc(label)}" class="${active?'active':''}" ${active?'aria-current="page"':''}><span class="nav-icon">${icon({assigned:'crm',program:'book',opportunities:'trend'}[id]||id)}</span><span class="nav-text">${label}</span>${page===id?`<span class="nav-current">${icon('arrow')}</span>`:''}</button>`;}
function sidebar(){return `<aside class="sidebar${state.sidebarCollapsed?' is-collapsed':''}" aria-label="Partner navigation"><div class="sidebar-header"><a class="brand" href="#dashboard" aria-label="PRM home"><span class="brand-mark"><i></i><i></i><i></i></span>PRM<span>.</span></a><button class="sidebar-toggle" data-action="sidebar-collapse" aria-label="${state.sidebarCollapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!state.sidebarCollapsed}">${icon(state.sidebarCollapsed?'expand':'collapse')}</button><button class="sidebar-close" data-action="menu-close" aria-label="Close navigation">×</button></div><button class="workspace" data-page="program"><span class="company-icon">${esc(initials(state.company.name))}</span><span class="workspace-copy"><b>${esc(state.company.name)}</b><span class="workspace-label">Partner workspace</span></span>${icon('down')}</button><button class="sidebar-create" data-action="quick"><span class="create-icon">${icon('plus')}</span><span class="create-label">Quick create</span><kbd>⌘ J</kbd></button><div class="sidebar-scroll"><div class="nav-group"><div class="nav-label">WORKSPACE</div><nav class="nav">${navButton('dashboard','Overview')}${navButton('leads','Leads')}${navButton('deals','Deal Registrations')}${navButton('opportunities','CRM Opportunities')}</nav></div><div class="nav-group"><div class="nav-label">MY PARTNERSHIP</div><nav class="nav">${navButton('crm','Salesforce updates')}${navButton('program','My program')}${navButton('security','Account & security')}</nav></div></div><div class="side-bottom"><button class="sidebar-help" data-action="support">${icon('help')}<span>How it works</span>${icon('arrow')}</button><button class="profile" data-page="security"><span class="avatar">${esc(initials(state.user.name))}</span><span class="profile-copy"><b>${esc(state.user.name)}</b><span class="tiny">Partner Manager</span></span>${icon('down')}</button></div></aside>`;}
let navigationOrigin=null;
function setNavigation(open){
  const nav=document.querySelector('.sidebar');
  if(!nav)return;
  nav.classList.toggle('open',open);
  document.querySelector('.mobile-shade')?.classList.toggle('show',open);
  document.querySelector('[data-action="menu"]')?.setAttribute('aria-expanded',String(open));
  const main=document.querySelector('.main');
  if(main)main.inert=open;
  if(open){navigationOrigin=document.activeElement;nav.querySelector('.sidebar-close')?.focus();}
  else if(navigationOrigin?.isConnected){navigationOrigin.focus();navigationOrigin=null;}
}

// Status updates re-render in place: the page only animates when you navigate, and scroll positions stay put.
let lastRenderedPage=null;
function render(){
 const inPortal=()=>state.signedIn&&state.onboarding===3,same=inPortal()&&lastRenderedPage===page,boards=[...document.querySelectorAll('.lead-board-scroll')].map(el=>el.scrollLeft),y=window.scrollY||0;
 renderPage();lastRenderedPage=inPortal()?page:null;
 if(same){document.querySelector('main.content')?.classList.remove('fade-in');document.querySelectorAll('.lead-board-scroll').forEach((el,i)=>{if(boards[i])el.scrollLeft=boards[i];});if(y&&window.scrollY!==y)window.scrollTo?.({top:y,behavior:'instant'});}
}
function renderPage(){if(!state.signedIn){renderWelcome();return;}if(state.onboarding!==3){renderEntry();return;}if(!pages[page])page='dashboard';window.history?.replaceState(null,'','#'+page);const unread=workflow.notifications().filter(n=>!n.read).length;document.getElementById('app').innerHTML=`<div class="mobile-shade" data-action="menu-close"></div>${sidebar()}<div class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span class="breadcrumb-home">${icon('team')} Partner workspace</span><span class="breadcrumb-divider">/</span><span>${page==='leads'&&leadScope==='all'?'Leads':pages[page]}</span></div><div class="top-actions">${syncStatus()}<button class="search-trigger" data-action="search" aria-label="Search records">${icon('search')}<span>Search records</span><kbd>⌘ K</kbd></button><button class="icon-btn" data-action="notifications" aria-label="Notifications${unread?', '+unread+' unread':''}">${icon('bell')}${unread?'<i class="dot"></i>':''}</button><button class="avatar top-avatar" data-page="security" aria-label="Your account">${esc(initials(state.user.name))}</button></div></header><main class="content fade-in">${views[page]()}<footer class="footer-note"><span>${icon('security')}Partner Manager access · Local Salesforce simulation</span><span>Every next step, connected.</span></footer></main></div>`;bindForms();enhanceTables();if(syncBusy)document.querySelectorAll('[data-sales-action="refresh"],[data-sales-action="retry"]').forEach(b=>{b.disabled=true;});scheduleReview();}
// Always-visible CRM sync status. Records can be created while disconnected; they wait here until Salesforce is connected.
function syncStatus(){
 const waiting=state.sales.outbox.filter(o=>o.partnerId===state.sales.partnerId&&['pending','failed'].includes(o.state)),failed=waiting.some(o=>o.state==='failed'),count=waiting.length+(waiting.length===1?' update':' updates');
 const [tone,label]=!state.crm.connected?['off','Salesforce not connected'+(waiting.length?' · '+count+' waiting':'')]:syncBusy?['busy','Syncing with Salesforce…']:failed?['failed','Salesforce sync failed · retry']:waiting.length?['busy',count+' waiting to sync']:['ok','Salesforce synced'+(state.sales.lastSync?' · '+new Date(state.sales.lastSync).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):'')];
 return `<button class="sync-status ${tone}" data-page="crm" title="Open Salesforce updates"><i></i><span>${label}</span></button>`;
}
function heading(title,sub,buttons='',className=''){return `<div class="page-heading${className?' '+className:''}"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${buttons}</div></div>`}
function btn(label,action,ic='plus',type=''){return `<button class="btn ${type.includes('light')?'btn-outline btn-secondary':'btn-primary'} ${type.includes('small')?'btn-sm':''} ${type}" data-action="${action}">${icon(ic)}${label}</button>`}
function task(title,sub,ic,action,time){return `<button class="task" data-action="${action}" ><span class="task-symbol">${icon(ic)}</span><span class="task-copy"><b>${title}</b><small>${sub}</small></span>${time?`<span class="task-time">${time}</span>`:''}<span class="task-arrow">›</span></button>`}
function statusLabel(status){return status==='Pending review'?'In Review':status;}
function stagePill(stage){const tone=['Qualified','Approved','Won'].includes(stage)?'':['Lost','Rejected','Disqualified','Declined','Closed','Withdrawn'].includes(stage)?'red':['Submitted','Qualification requested','Pending review','Needs information'].includes(stage)?'amber':['Draft','Disconnected','Not created'].includes(stage)?'neutral':'blue';return `<span class="badge pill ${tone}"><i></i>${esc(statusLabel(stage))}</span>`;}
// Lead stages use partner-facing names; Converted is derived from an active linked deal.
const leadLabel=status=>({Draft:'New',Submitted:'New',Approved:'New',Assigned:'New',Accepted:'New','Needs information':'New',Working:'Contacted',Rejected:'Disqualified',Declined:'Closed',Converted:'Converted'})[status]||status;
function leadPill(r){const stage=workflow.leadStage(r),label=leadLabel(stage),tone=['Qualified','Converted'].includes(label)?'':['Disqualified','Closed'].includes(label)?'red':label==='New'?'neutral':'blue';return `<span class="badge pill ${tone}"><i></i>${esc(leadLabel(stage))}</span>`;}
function leadIntake(r){return ({Draft:'Not submitted',Submitted:'Vendor review pending','Needs information':'Information requested',Approved:'Ready for first contact',Assigned:'Awaiting acceptance',Accepted:'Accepted · contact customer',Rejected:'Vendor declined',Declined:'Assignment declined'})[r.status]||'';}
function leadChips(r){
 const stage=workflow.leadStage(r),deadline=workflow.leadDeadline(r),chips=[];
 if(r.rating)chips.push(`<span class="pill neutral"><i></i>${esc(r.rating)}</span>`);
 if(deadline?.kind==='accept')chips.push(deadline.overdue?'<span class="pill red">Response overdue</span>':`<span class="pill amber">Accept within ${deadline.hoursLeft}h</span>`);
 else if(deadline?.kind==='contact')chips.push(deadline.overdue?'<span class="pill red">First contact overdue</span>':`<span class="pill amber">Contact within ${deadline.hoursLeft>24?deadline.daysLeft+' days':deadline.hoursLeft+'h'}</span>`);
 else if(stage==='Working')chips.push(`<span class="pill blue">BANT ${workflow.bant(r).count}/4</span>`);
 else if(stage==='Approved'&&deadline)chips.push(`<span class="pill blue">Protected · ${deadline.daysLeft} days</span>`);
 else if(stage==='Qualified')chips.push('<span class="pill">Ready to register</span>');
 else if(stage==='Needs information')chips.push('<span class="pill amber">Action needed</span>');
 return chips.length?`<div class="lead-card-chips">${chips.join('')}</div>`:'';
}
function companyLogo(name){const colors=['sage','lavender','sand','blue','rose'];let n=[...name].reduce((a,c)=>a+c.charCodeAt(0),0);return `<span class="company-logo ${colors[n%5]}">${esc(name.slice(0,1).toUpperCase())}</span>`}
