let fieldId=0;
function field(label,name,value='',type='text',required=true){let uid='f-'+name+'-'+(++fieldId);return `<div class="field"><label class="form-label" for="${uid}">${label}</label><input class="form-control" id="${uid}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" max="1000000000" step="1"':''}></div>`}
function select(label,name,options,value){let uid="f-"+name+"-"+(++fieldId);return `<div class="field"><label class="form-label" for="${uid}">${label}</label><select class="form-select" id="${uid}" name="${name}">${options.map(s=>`<option ${s===value?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`}
function onboardingDial(step){
  const progress=1;
  const ticks=Array.from({length:60},(_,i)=>{
    const angle=i*Math.PI/30-Math.PI/2;
    const inner=i%5===0?114:119;
    const point=r=>[140+Math.cos(angle)*r,140+Math.sin(angle)*r].map(n=>n.toFixed(2));
    const [x1,y1]=point(inner),[x2,y2]=point(125);
    return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="dial-tick ${i%5===0?'major':''} ${i<progress*60?'lit':''}"/>`;
  }).join('');
  const angle=progress*Math.PI*2-Math.PI/2;
  const x=(140+Math.cos(angle)*103).toFixed(2),y=(140+Math.sin(angle)*103).toFixed(2);
  return `<div class="entry-art"><div class="entry-dial" role="img" aria-label="60 seconds to get going. ${step===null?'Your partner workspace, one minute away.':`Setup step ${step+1} of 3.`}"><svg class="dial-artwork" viewBox="0 0 280 280" aria-hidden="true"><defs><linearGradient id="dial-accent" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffcf99"/><stop offset="1" stop-color="#ffb359"/></linearGradient><radialGradient id="dial-face"><stop stop-color="#204c80"/><stop offset="1" stop-color="#13365f"/></radialGradient></defs><circle class="dial-outline" cx="140" cy="140" r="136"/><g class="dial-orbit"><circle class="dial-orbit-trail" cx="140" cy="140" r="136" pathLength="100" stroke-dasharray="7 93" transform="rotate(-115.2 140 140)"/><circle class="dial-orbit-glow" cx="140" cy="4" r="5"/><circle class="dial-orbit-dot" cx="140" cy="4" r="2"/></g>${ticks}<circle class="dial-surface" cx="140" cy="140" r="97" fill="url(#dial-face)"/><circle class="dial-track" cx="140" cy="140" r="103"/><circle class="dial-progress" cx="140" cy="140" r="103" pathLength="100" stroke="url(#dial-accent)" stroke-dasharray="${(progress*100).toFixed(2)} 100" transform="rotate(-90 140 140)"/><circle class="dial-tip-halo" cx="${x}" cy="${y}" r="7"/><circle class="dial-tip" cx="${x}" cy="${y}" r="3.5"/></svg><div class="dial-center" aria-hidden="true"><span class="dial-emblem">${icon('bolt')}</span><strong>60</strong><span class="dial-unit">SECONDS</span><span class="dial-promise">to get going</span></div></div><div class="dial-caption"><span>${icon('check')}</span>Built for your next big move.</div></div>`;
}
function entryStory(step=null){return `<aside class="entry-story"><div class="brand"><span class="brand-mark"><i></i><i></i><i></i></span>PRM<span>.</span></div><div class="entry-story-content"><div class="entry-kicker">GOOD PARTNERSHIPS START HERE</div><h1>A small start.<br>A world of<br><em>possibility.</em></h1><p>Less setup. More momentum.<br>Your partner workspace is just a minute away.</p>${onboardingDial(step)}</div><div class="entry-story-footer">A little progress. A bigger partnership.</div></aside>`;}
