function enterManagerPortal(){try{sessionStorage.setItem('prm-manager-session','1');}catch{}location.href='manager.html#overview';}
function renderPortalChoice(){
  const card=(id,ic,title,text,cta)=>`<button id="${id}" class="portal-card" type="button"><span class="portal-icon">${icon(ic)}</span><span class="portal-copy"><b>${title}</b><small>${text}</small><span class="portal-cta">${cta} ${icon('arrow')}</span></span></button>`;
  document.getElementById('app').innerHTML=`<main class="entry-layout welcome-layout">${entryStory()}<section class="entry-main welcome-main" aria-labelledby="welcome-title"><div class="welcome-content fade-in"><span class="welcome-eyebrow">YOUR PARTNER WORKSPACE</span><h2 id="welcome-title">Welcome to PRM.</h2><p class="welcome-description">Choose your portal to get started.</p><div class="portal-cards">${card('portal-partner','deals','Partner Manager','Register leads and deals, and track every opportunity to close.','Continue as Partner Manager')}${card('portal-manager','team','Partner Account Manager','Approve registrations, distribute leads, and track partner performance.','Continue as Partner Account Manager')}</div><p class="welcome-demo-note">Local preview · Both portals share one simulated Salesforce.</p></div><footer class="welcome-footer">A little progress. A bigger partnership.</footer></section></main>`;
  document.getElementById('portal-partner').onclick=()=>{welcomeRole='partner';renderWelcome();document.getElementById('welcome-title')?.focus();};
  document.getElementById('portal-manager').onclick=()=>{welcomeRole='manager';renderWelcome();document.getElementById('welcome-title')?.focus();};
}
function renderWelcome(){
  window.history?.replaceState(null,'','#welcome');
  if(!['partner','manager'].includes(welcomeRole)){renderPortalChoice();return;}
  const manager=welcomeRole==='manager',enter=email=>manager?enterManagerPortal():beginOnboarding(email);
  document.getElementById('app').innerHTML=`<main class="entry-layout welcome-layout">${entryStory()}<section class="entry-main welcome-main" aria-labelledby="welcome-title"><div class="welcome-content fade-in"><button id="welcome-back" class="welcome-back" type="button">← Choose a different portal</button><span class="welcome-eyebrow">${manager?'PARTNER ACCOUNT MANAGER SIGN-IN':'PARTNER MANAGER SIGN-IN'}</span><h2 id="welcome-title" tabindex="-1">Welcome to PRM.</h2><p class="welcome-description">${manager?'Review registrations and run your partner program.<br>Sign in to continue.':'Good partnerships start with a hello.<br>Sign in to get yours going.'}</p><div class="welcome-providers"><button id="google-login" class="btn welcome-google" type="button" aria-describedby="welcome-demo-note">${googleMark()}Continue with Google</button><button id="microsoft-login" class="btn welcome-google" type="button" aria-describedby="welcome-demo-note">${microsoftMark()}Continue with Microsoft</button><button id="sso-login" class="btn welcome-google" type="button" aria-describedby="welcome-demo-note">${icon('security')}Continue with SSO</button></div><div class="welcome-divider"><span>or sign in with email</span></div><form id="welcome-login-form" aria-describedby="welcome-demo-note"><div class="welcome-field"><label for="welcome-email">Email address</label><input class="form-control" id="welcome-email" name="email" type="email" placeholder="you@company.com" autocomplete="username" required></div><div class="welcome-field"><label for="welcome-password">Password</label><div class="welcome-password"><input class="form-control" id="welcome-password" name="password" type="password" placeholder="Enter a demo password" autocomplete="current-password" required><button id="password-visibility" type="button" aria-label="Show password" aria-pressed="false" aria-controls="welcome-password">Show</button></div></div><button class="btn btn-primary welcome-submit" type="submit">Sign in ${icon('arrow')}</button></form><p id="welcome-demo-note" class="welcome-demo-note">Local preview · All sign-in options are simulated.<br>Use demo details. Passwords are never saved or sent.</p></div><footer class="welcome-footer">A little progress. A bigger partnership.</footer></section></main>`;
  document.getElementById('welcome-back').onclick=()=>{welcomeRole=null;renderWelcome();};
  for(const provider of ['google-login','microsoft-login','sso-login'])document.getElementById(provider).onclick=()=>enter();
  document.getElementById('welcome-login-form').onsubmit=e=>{
    e.preventDefault();
    if(!e.target.reportValidity())return;
    const email=String(new FormData(e.target).get('email')).trim();
    e.target.reset();
    enter(email);
  };
  document.getElementById('password-visibility').onclick=e=>{
    const input=document.getElementById('welcome-password');
    const reveal=input.type==='password';
    input.type=reveal?'text':'password';
    e.currentTarget.textContent=reveal?'Hide':'Show';
    e.currentTarget.setAttribute('aria-label',reveal?'Hide password':'Show password');
    e.currentTarget.setAttribute('aria-pressed',String(reveal));
  };
}
function programOverview(){
  return `<section class="card program-card" aria-labelledby="program-name"><header class="program-header"><div><h3 id="program-name">Resell partner</h3><p>Your assigned partner program.</p></div><span class="program-label">${icon('security')}View only</span></header><div class="program-benefits"><div class="program-margin"><strong>25<span>%</span></strong><span>resell margin</span></div><ul class="program-perks"><li>${icon('check')}90-day deal protection</li><li>${icon('check')}Dedicated partner account manager</li><li>${icon('check')}Volume-based incentives</li></ul></div></section>
  <section class="card program-requirements" aria-labelledby="requirements-title"><h3 id="requirements-title">Your program requirements</h3><ol><li><span class="requirement-number">01</span><span>Partner &amp; data agreements</span><span class="requirement-timing">During setup</span></li><li><span class="requirement-number">02</span><span>W-9 and insurance certificate</span><span class="requirement-timing">During setup</span></li><li><span class="requirement-number">03</span><span>One certified seller within 30 days</span><span class="requirement-timing after">After approval</span></li></ol></section>`;
}
function openSetupConnection(){
  if(!state.signedIn||(state.onboarding!==3&&state.setupStep!==0))return;
  connectionPending=true;
  modal('Connect Salesforce','Review the connection before continuing.',`<div class="connection-review"><div class="connection-account">${salesforceMark()}<div><strong>${esc(state.company.name)}</strong><span>Salesforce demo environment</span></div></div><h3>PRM will connect these records</h3><ul><li>${icon('check')}Company accounts and contacts</li><li>${icon('check')}Partner leads and opportunities</li><li>${icon('check')}Deal stages and pipeline updates</li></ul><div class="connection-actions"><button class="btn btn-outline btn-secondary" data-action="close">Cancel</button><button id="confirm-setup-connection" class="btn btn-primary">Connect demo Salesforce ${icon('arrow')}</button></div></div>`);
  document.getElementById('confirm-setup-connection').onclick=confirmSetupConnection;
}
function confirmSetupConnection(){
  if(!connectionPending||!state.signedIn||(state.onboarding!==3&&state.setupStep!==0))return;
  const inPortal=state.onboarding===3;state.crmSkipped=false;
  state.crm={name:'Salesforce',connected:true,lastSync:'Ready for first sync'};
  closeModal();save();if(inPortal){render();toast('Salesforce simulation connected. Syncing your saved updates.');startSalesSync();return;}renderEntry();
  document.querySelector('[data-entry="next"]')?.focus();
}
function handleEntryAction(action){
  if(!state.signedIn){renderWelcome();return;}
  if(action==='connect'){openSetupConnection();return;}
  if(action==='skip'&&state.setupStep===0){state.crmSkipped=true;state.setupStep=1;}
  if(action==='back')state.setupStep=0;
  if(action==='next'){
    if(!state.crm.connected)return;
    state.setupStep=1;
  }
  if(action==='finish'){
    if(!state.crm.connected&&!state.crmSkipped){state.setupStep=0;save();renderEntry();return;}
    if(state.setupStep!==1)return;
    state.onboarding=3;
    log('Onboarding complete',state.company.name+' joined the workspace');
    page='dashboard';save();render();window.scrollTo(0,0);
    document.querySelector('.page-heading h1')?.focus();
    toast('Welcome to PRM. Your workspace is ready.');return;
  }
  save();renderEntry();
  if(action!=='connect'){window.scrollTo(0,0);document.getElementById('setup-title')?.focus();}
  else document.querySelector('[data-entry="next"]')?.focus();
}
function renderEntry(){
  if(!state.signedIn){renderWelcome();return;}
  window.history?.replaceState(null,'','#onboarding');
  const step=(state.crm.connected||state.crmSkipped)?Math.min(1,state.setupStep||0):0;
  state.setupStep=step;
  const body=step===0?`<section class="card setup-crm-card" aria-labelledby="crm-setup-title"><div class="setup-crm-identity">${salesforceMark()}<span class="setup-link" aria-hidden="true">${icon('crm')}</span><span class="setup-prm-mark">PRM<span>.</span></span></div><h3 id="crm-setup-title">Salesforce + PRM</h3><p>Your accounts, leads, and opportunities.<br>One connected partner workspace.</p><div class="setup-sync-items"><span>${icon('check')}Accounts</span><span>${icon('check')}Leads</span><span>${icon('check')}Opportunities</span></div><div class="setup-connection">${state.crm.connected?`<span class="setup-connected">${icon('check')}Salesforce demo connected</span><p>You’re ready to explore your partner program.</p>`:`<button class="btn btn-primary" data-entry="connect">Connect Salesforce ${icon('arrow')}</button><button class="text-link setup-connect-later" data-entry="skip">Connect later ${icon('arrow')}</button><p class="setup-optional-note">No Salesforce account? You can still use your partner workspace.</p>`}</div></section>`:programOverview();
  document.getElementById('app').innerHTML=`<main class="setup-layout"><header class="setup-top"><div class="brand" aria-label="PRM"><span class="brand-mark"><i></i><i></i><i></i></span>PRM<span>.</span></div><span class="setup-top-note">YOUR PARTNER WORKSPACE</span></header><section class="setup-shell ${step===0?'setup-connect':'setup-program'}" aria-labelledby="setup-title"><ol class="setup-progress" aria-label="Onboarding progress">${['Connect CRM','Your program'].map((label,i)=>`<li class="${i===step?'current':i<step?'complete':''}" ${i===step?'aria-current="step"':''}><span>${i<step?(i===0&&!state.crm.connected?'—':icon('check')):i+1}</span>${label}${i===0&&i<step&&!state.crm.connected?' · Skipped':''}</li>`).join('')}</ol><div class="setup-heading"><span class="setup-step-label">STEP ${step+1} OF 2</span><h1 id="setup-title" tabindex="-1">${step===0?'Bring your CRM along.':'Your partner program.'}</h1><p>${step===0?'Connect Salesforce now, or continue and connect later.':'Your benefits, your commitments, and a clear path forward.'}</p></div><div class="setup-content fade-in">${body}</div><footer class="setup-actions">${step===0?`<span>${icon('security')}Local demo · No data is transferred</span><button class="btn btn-primary" data-entry="next" ${state.crm.connected?'':'disabled'}>View your program ${icon('arrow')}</button>`:`<button class="text-link" data-entry="back">← Back to connection</button><button class="btn btn-primary" data-entry="finish">Enter dashboard ${icon('arrow')}</button>`}</footer><p class="setup-footnote">${step===0?'Your saved workspace stays on this device.':'Program preview · For your reference. No documents or agreement acceptance are required in this demo.'}</p></section></main>`;
  document.querySelectorAll('[data-entry]').forEach(el=>el.addEventListener('click',()=>handleEntryAction(el.dataset.entry)));
}
function salesforceMark(){return '<span class="salesforce-mark"><img src="assets/salesforce-logo.webp" alt="Salesforce" width="1280" height="894"></span>'}
function security(){return `${heading('Account & security','Your profile, access preferences, and workspace session.')}<div class="banner">${icon('security')} Local demo workspace · Sign-in and verification are preview experiences.</div><div class="form-layout"><section class="card panel form-panel"><h3>Your profile</h3><form id="profile-form">${field('Full name','name',state.user.name)}${field('Email address','email',state.user.email,'email')}<button class="btn btn-primary" type="submit">Save profile</button></form></section><section class="card panel form-panel"><h3>Access preferences</h3><div class="settings-row"><div><b>Two-step verification</b><p>Preview the verification preference. Real MFA requires an identity provider.</p></div><button class="toggle ${state.settings.mfa?'on':''}" data-toggle="mfa" role="switch" aria-checked="${state.settings.mfa}" aria-label="Two-step verification"><span></span></button></div><div class="settings-row"><div><b>Current session</b><p>Demo workspace · This browser</p></div><span class="badge pill">Active</span></div><div class="settings-row"><div><b>Sign out of the demo</b><p>Your saved workspace will remain on this device.</p></div>${btn('Sign out','logout','logout','light small')}</div></section></div>`}
const views={dashboard,leads:salesList,assigned:salesList,deals:salesList,opportunities:salesList,crm,program,security};
let modalOrigin=null,modalLeadId=null;
function closeModal(){cardFlow=null;document.getElementById('app').inert=false;connectionPending=false;document.getElementById('overlay').innerHTML='';if(modalOrigin?.isConnected)modalOrigin.focus();else if(modalLeadId)document.querySelector(`[data-sales-id="${modalLeadId}"]`)?.focus();modalOrigin=null;modalLeadId=null;detailRecord=null;}
function modal(title,sub,body,wide=false){detailRecord=null;document.getElementById('app').inert=true;if(!document.querySelector('.app-dialog'))modalOrigin=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="dialog-backdrop"><section class="app-dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><p class="modal-sub">${sub}</p>${body}</section></div>`;setTimeout(()=>(document.querySelector('.app-dialog input')||document.querySelector('.app-dialog .action-choice')||document.querySelector('.app-dialog .btn')||document.querySelector('.app-dialog .close'))?.focus(),30)}
let salesView=state.leadView==='list'?'list':'board',salesQuery='',salesFilter='All statuses',salesSort='updated',leadScope='partner',detailRecord=null,syncBusy=false,showAllActions=false;
const salesType=()=>['deals','opportunities'].includes(page)?'deal':'lead';
const labelStatus=r=>r.registration?(r.registration==='Approved'?r.stage:r.registration):workflow.leadStage(r);
const salesDate=v=>v?new Date(v.length===10?v+'T12:00:00Z':v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Kolkata'}):'Not set';
const salesTime=v=>new Date(v).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'Asia/Kolkata'});
function salesButton(label,action,type='',id='',light=false){return `<button type="button" class="btn ${light?'btn-outline btn-secondary':'btn-primary'}" data-sales-action="${action}" ${type?`data-sales-type="${type}"`:''} ${id?`data-sales-id="${id}"`:''}>${label}</button>`;}
function getRecord(type,id){return workflow.get(type,id);}
function recordAction(r,type){
 const today=new Date().toISOString().slice(0,10),followUp=(r.activities||[]).find(a=>a.type==='Follow-up'&&!a.completed&&a.dueDate<today);
 const next=value=>followUp&&value.action?{...value,detail:'Follow-up overdue: '+followUp.note+' · '+value.detail}:value;
 if(r.sync.status==='failed')return next({label:'Retry Salesforce sync',action:'retry',detail:r.sync.error});
 const submitting=type==='lead'?['Draft','Needs information'].includes(r.status):['Draft','Rejected'].includes(r.registration);
 const waiting={label:'Processing submission',action:'',loading:true,detail:type==='lead'?'The simulated vendor is validating this lead. Your next action appears after the update.':'The simulated vendor is checking this registration. Qualification, registration approval, and a won opportunity are separate events.'};
 if(['pending','syncing'].includes(r.sync.status)&&syncBusy)return next(submitting?waiting:{label:'Sending to Salesforce',action:'',loading:true,detail:'Your update is on its way. This takes a moment.'});
 if(['pending','syncing'].includes(r.sync.status))return next({label:'Sync queued update',action:'retry',detail:'Your update is saved. Salesforce must confirm it before the record changes.'});
 if(type==='deal'){
  if(r.registration==='Expired')return {label:'View registrations',action:'back-list',detail:r.reason||'This registration has expired. Contact your vendor before registering again.'};
  if(r.registration==='Withdrawn')return {label:'',action:'',detail:r.withdrawReason||'This registration was withdrawn. No further partner action is required.'};
  if(r.registration==='Draft')return next({label:'Review & submit',action:'submit-deal',detail:'Send it to your partner account manager for approval. Approval protects the deal for 90 days and creates the CRM opportunity.'});
  if(['Submitted','Pending review'].includes(r.registration))return next(reviewJob(r.crmId)?waiting:{label:'Check registration status',action:'refresh',detail:r.reason||'Your partner account manager is reviewing this registration.'});
  if(r.registration==='Rejected')return next({label:'Revise registration',action:'edit',detail:r.reason});
  if(['Won','Lost'].includes(r.stage))return next({label:'Add a note',action:'activity',detail:r.stage==='Won'?'The opportunity is won. Coordinate delivery with the vendor.':r.outcomeReason||'This opportunity is closed lost.'});
  if(page!=='opportunities'&&r.opportunityId)return next({label:'Track opportunity',action:'opportunity-detail',detail:r.expectedClose&&r.expectedClose<today?'Expected close date has passed. Update the close date or move the stage.':'Registration approved. Follow '+r.opportunityId+' through the sales stages; its current stage is '+r.stage+'.'});
  return next({label:'Update opportunity',action:'stage',detail:r.expectedClose&&r.expectedClose<today?'Expected close date has passed. Update the close date or move the stage.':'Registration approved and CRM opportunity created. Report each sales stage as the deal moves.'});
 }
 const stage=workflow.leadStage(r),deadline=workflow.leadDeadline(r);
 if(['Closed','Rejected','Declined'].includes(stage))return {label:'',action:'',detail:r.reviewReason||r.closeReason||'This lead is closed.'};
 if(r.dealId){try{const d=getRecord('deal',r.dealId);return next(d.registration==='Withdrawn'?{label:'Register deal',action:'register-linked',detail:'The previous deal registration was withdrawn. Register the deal again when the customer is ready.'}:{label:'View deal registration · '+(d.stage||statusLabel(d.registration)),action:'linked',detail:'Deal registration '+d.id+' · '+statusLabel(d.registration)+' · CRM opportunity '+(d.stage||'not created yet')});}catch{}}
 if(stage==='Draft')return next({label:'Submit for approval',action:'submit-lead',detail:'Send this lead to the vendor. They check that no other partner has registered this customer and that it is in your territory.'});
 if(stage==='Submitted'&&reviewJob(r.crmId))return next(waiting);
 if(stage==='Submitted')return next({label:'Check approval status',action:'refresh',detail:'Your partner account manager is checking it for duplicates, territory, and missing details. Their decision arrives here as soon as they make it.'});
 if(stage==='Needs information')return next({label:'Update & resubmit',action:'resubmit',detail:r.reviewReason||'The vendor needs more information before approving this lead.'});
 if(stage==='Assigned')return next({label:'Accept lead',action:'accept',detail:deadline?.overdue?'The response deadline has passed. Accept now, or decline so the vendor can reassign it.':'The vendor sent you this lead. Accept it within '+(deadline?.hoursLeft??48)+' hours, or decline it with a reason.'});
 if(stage==='Approved')return next({label:'Log first contact',action:'first-contact',detail:'Approved by the vendor, so this customer is yours to pursue'+(r.protectedUntil?' until '+salesDate(r.protectedUntil):'')+'. Call, email, or meet them, then log it here.'});
 if(stage==='Accepted')return next({label:'Log first contact',action:'first-contact',detail:deadline?.overdue?'First contact is overdue. Reach the customer and log the call, email, or meeting.':'Reach the customer by '+salesTime(deadline?.due||r.updatedAt)+' and log the call, email, or meeting.'});
 if(stage==='Working')return next({label:'Qualify lead',action:'qualify',detail:'Confirm budget, authority (the decision maker), need, and timeline — BANT. '+workflow.bant(r).count+' of 4 confirmed so far.'});
 if(stage==='Qualified')return next({label:'Register deal',action:'register-linked',detail:'This lead is qualified. Register the deal so your vendor can approve it, protect it for 90 days, and open the CRM opportunity.'});
 return {label:'',action:'',detail:r.reviewReason||'No further partner action is required.'};
}
function syncBadge(r){const status=syncBusy&&r.sync.status==='pending'?'syncing':r.sync.status;return `<span class="sync-badge ${status}" title="${esc(r.sync.error||'')}">${status==='synced'?icon('check'):status==='failed'?icon('help'):icon('clock')}${{local:'New · not submitted',synced:'Salesforce confirmed',pending:'Sync pending',syncing:'Syncing…',failed:'Sync failed'}[status]}</span>`;}
function scopedRecords(type=salesType()) {return workflow.list(type).filter(r=>type==='deal'?page!=='opportunities'||r.registration==='Approved'&&!!r.opportunityId:(page==='assigned'?r.origin==='crm':leadScope==='all'||r.origin==='partner'));}
// The board column for a record on this page: lead stage, registration status, or CRM opportunity stage.
const boardStage=r=>r.registration?(page==='opportunities'?r.stage:r.registration):workflow.leadStage(r);
const recordOrNull=(type,id)=>{try{return id?getRecord(type,id):null;}catch{return null;}};
// Lead columns follow the real lead lifecycle; terminal outcomes share one Closed column.
const LEAD_COLUMNS={leads:[['Draft','New',['Draft','Submitted','Needs information','Approved','Assigned','Accepted']],['Working','Contacted',['Working']],['Qualified','Qualified',['Qualified']],['Converted','Converted',['Converted']],['Closed','Disqualified / Closed',['Closed','Rejected','Declined']]],assigned:[['Draft','New',['Assigned','Accepted']],['Working','Contacted',['Working']],['Qualified','Qualified',['Qualified']],['Converted','Converted',['Converted']],['Closed','Disqualified / Closed',['Closed','Declined']]]};
function salesColumns(type){return type==='deal'?(page==='opportunities'?['Discovery','Proposal','Negotiation','Won','Lost']:['Draft','Submitted','Pending review','Approved','Rejected','Expired','Withdrawn']).map(status=>({key:status,label:statusLabel(status),match:[status]})):LEAD_COLUMNS[page==='assigned'?'assigned':'leads'].map(([key,label,match])=>({key,label,match}));}
const columnOf=(r,columns)=>columns.find(col=>col.match.includes(boardStage(r)));
function salesList(){
 const type=salesType(),all=scopedRecords(type),columns=salesColumns(type);
 const list=all.filter(r=>(salesFilter==='All statuses'||salesFilter==='Active'&&r.registration==='Approved'&&!['Won','Lost'].includes(r.stage)||salesFilter==='Pending'&&['Submitted','Pending review'].includes(r.registration)||salesFilter==='Attention'&&needsPartnerAction(r,type)||columnOf(r,columns)?.key===salesFilter)&&[r.company,r.contact,r.email,r.source,r.receivedFrom,r.id,r.name].join(' ').toLowerCase().includes(salesQuery.toLowerCase())).sort((a,b)=>salesSort==='company'?a.company.localeCompare(b.company):salesSort==='value'?b.value-a.value:String(b[salesSort==='created'?'createdAt':'updatedAt']||'').localeCompare(String(a[salesSort==='created'?'createdAt':'updatedAt']||''))||(page==='assigned'?b.id.localeCompare(a.id,undefined,{numeric:true}):0));
 const title=page==='leads'&&leadScope==='all'?'Leads':pages[page],tabCount=p=>p==='opportunities'?workflow.list('deal').filter(r=>r.registration==='Approved'&&r.opportunityId).length:p==='deals'?workflow.list('deal').length:workflow.list('lead').filter(r=>r.origin===(p==='assigned'?'crm':'partner')).length;
 const subtitle={leads:'Create or select a lead, contact the customer, and qualify the opportunity before registering a deal.',assigned:'Leads your vendor sends you. Accept within 48 hours, work them, and register qualified ones as deals.',deals:'Requests to register a specific opportunity with your vendor. Approval protects the deal for 90 days and creates a CRM opportunity.',opportunities:'Approved deal registrations become opportunities in the vendor’s CRM. Keep stage, value, and close date current.'}[page];
 const actions=salesButton(syncBusy?'Syncing…':'Refresh Salesforce','refresh','','',true)+(page==='assigned'?'':salesButton(type==='deal'?'Register deal':'Create lead',type==='deal'?'new-deal':'new-lead'));
 return `<div class="pipeline-page">${heading(title,subtitle,actions)}${['leads','assigned'].includes(page)?`<div class="sales-category-tabs" aria-label="Lead lists">${[['all','All leads',workflow.list('lead').length],['partner','My leads',tabCount('leads')],['crm','CRM assigned',tabCount('assigned')]].map(([scope,label,count])=>`<button data-sales-action="source-filter" data-scope="${scope}" class="${(page==='assigned'?'crm':leadScope)===scope?'active':''}">${label}<span>${count}</span></button>`).join('')}</div>`:''}<div class="pipeline-toolbar"><div class="search-field">${icon('search')}<input id="sales-search" class="form-control" placeholder="Search company, contact, or record" aria-label="Search sales records" value="${esc(salesQuery)}"></div><select class="form-select sales-status-filter" id="sales-filter" aria-label="Filter status"><option value="All statuses" ${salesFilter==='All statuses'?'selected':''}>All statuses</option>${['Active','Pending','Attention'].includes(salesFilter)?`<option selected value="${salesFilter}">${{Active:'Active opportunities',Pending:'Pending registrations',Attention:'Needs your action'}[salesFilter]}</option>`:''}${columns.map(col=>`<option value="${esc(col.key)}" ${col.key===salesFilter?'selected':''}>${esc(col.label)}</option>`).join('')}</select><select class="form-select sales-sort" id="sales-sort" aria-label="Sort records">${[['updated','Recently updated'],['created','Newest first'],['company','Company A–Z'],['value','Highest value']].map(([key,label])=>`<option value="${key}" ${salesSort===key?'selected':''}>${label}</option>`).join('')}</select><div class="pipeline-toolbar-actions"><div class="lead-view-toggle" role="group" aria-label="Record view">${[['board','Flow','dashboard'],['list','List','menu']].map(([view,label,ic])=>`<button data-sales-view="${view}" class="${salesView===view?'active':''}" aria-pressed="${salesView===view}">${icon(ic)}${label}</button>`).join('')}</div>${salesButton('Export','export','','',true)}</div></div><div class="pipeline-subbar"><span>${list.length} of ${all.length} records</span><span class="tiny">${page==='opportunities'?'Discovery → Proposal → Negotiation → Won or Lost':page==='deals'?'Approval creates the CRM opportunity · it doesn’t mean the deal is won':'New → Contacted → Qualified → Converted · vendor review is separate'}</span></div>${salesView==='list'?salesTable(list,type):salesBoard(list,type,columns)}<div class="pipeline-footer"><span>${icon('security')}Only records shared with ${esc(state.company.name)}</span><span>Select a record for its next action</span></div></div>`;
}
function recordOpen(r,type,content,cls=''){return `<button class="${cls}" data-sales-action="open" data-sales-type="${type}" data-sales-id="${r.id}">${content}</button>`;}
function salesVendor(r){const names=['NexaCloud','Vertex Software','Aster Platforms'];return r.vendorCompany||names[[...String(r.leadId||r.id)].reduce((sum,c)=>sum+c.charCodeAt(0),0)%names.length];}
function salesCard(r,type){const next=recordAction(r,type);return `<article class="card lead-card sales-card${flashId===r.id?' is-flash':''}" data-record="${type}:${r.id}">${recordOpen(r,type,`<div class="lead-card-heading"><h3>${esc(r.company)}</h3>${icon('arrow')}</div><p class="lead-card-contact">${esc(r.contact)}</p><div class="lead-card-value"><strong>${leadCompactMoney(r.value)}</strong><span class="tiny">${r.id}</span></div><div class="sales-card-route">${type==='deal'?(page==='opportunities'?`<span>CRM OPPORTUNITY · ${esc(r.opportunityId)}</span><b>${esc(r.product)} · close ${salesDate(r.expectedClose)}</b>`:`<span>${r.leadId?'FROM QUALIFIED LEAD '+esc(r.leadId):'DIRECT REGISTRATION'}</span><b>${esc(r.product)}</b>`):r.origin==='crm'?`<span>From vendor · ${esc(salesVendor(r))}</span><b>To partner · ${esc(state.company.name)}</b>`:`<b>To vendor · ${esc(salesVendor(r))}</b>`}</div>${type==='deal'?dealCardLabel(r):`<div class="lead-context"><span>${esc(r.source||'Vendor CRM')}</span><span>${esc(leadIntake(r)||leadLabel(workflow.leadStage(r)))}</span></div>`+leadChips(r)}`,'sales-card-open')}<div class="sales-card-foot"><div class="lead-next-step"><span>NEXT STEP</span>${next.loading?loadingButton(next.label,'lead-next-action'):next.action?`<button type="button" class="lead-next-action" data-sales-action="${next.action}" data-sales-type="${type}" data-sales-id="${r.id}" data-card="1">${esc(next.label)}${icon('arrow')}</button>`:`<p>${esc(next.label||next.detail)}</p>`}</div><footer>${syncBadge(r)}</footer></div></article>`;}
function dealCardLabel(r){if(page==='opportunities')return r.protectedUntil?`<div class="sales-registration-label">Protected until ${salesDate(r.protectedUntil)}</div>`:'';return r.opportunityId?`<div class="sales-registration-label">CRM opportunity ${stagePill(r.stage)}</div>`:'';}
// Busy columns show a few cards; View all opens the complete filtered list.
const CARD_LIMITS={lead:{Draft:2,Submitted:1,Closed:1},deal:{Draft:2}};
function salesBoard(list,type,columns){return `<div class="lead-board-scroll" tabindex="0" role="region" aria-label="Sales workflow. Scroll to see later stages."><div class="lead-board sales-board" style="--stage-count:${columns.length}">${columns.map(col=>{const rows=list.filter(r=>col.match.includes(boardStage(r))),limit=CARD_LIMITS[type][col.key],visibleRows=limit?rows.slice(0,limit):rows,noun=type==='lead'?'new leads':'draft registrations';return `<section class="lead-column" data-stage="${esc(col.key)}" style="--stage-color:${(type==='deal'?['Approved','Won']:['Qualified','Converted']).includes(col.key)?'#168467':['Lost','Rejected','Disqualified','Closed','Withdrawn','Declined'].includes(col.key)?'#bc5271':'#0969da'}"><header class="lead-column-header"><div><span class="lead-stage-marker"></span><h2>${esc(col.label)}</h2><span class="column-count">${rows.length}</span><strong>${leadCompactMoney(rows.reduce((n,r)=>n+r.value,0))}</strong></div><div class="lead-stage-line"><span style="width:${rows.length?100:0}%"></span></div></header><div class="lead-column-body">${visibleRows.map(r=>salesCard(r,type)).join('')||'<div class="lead-column-empty"><span>No records</span><small>Records move here as the workflow progresses.</small></div>'}${limit&&rows.length>limit?col.key==='Draft'?`<button class="draft-overflow" data-sales-action="all-drafts"><span>Showing ${limit} of ${rows.length} ${noun}</span><b>View all ${noun} ${icon('arrow')}</b></button>`:`<button class="draft-overflow" data-sales-action="all-status" data-sales-status="${esc(col.key)}"><span>Showing ${limit} of ${rows.length} records</span><b>View all ${esc(col.label.toLowerCase())} ${icon('arrow')}</b></button>`:''}</div></section>`}).join('')}</div></div>`;}
function salesTable(list,type){return `<section class="card pipeline-list"><div class="table-responsive table-wrap"><table class="table table-vcenter data-table"><thead><tr><th>Company & contact</th><th>Source / destination</th><th>Owner</th><th>Last activity</th><th>${type==='deal'?'Registration':'Stage'}</th>${type==='deal'?'<th>Opportunity</th>':''}<th class="numeric">Estimated value</th><th>Sync</th><th>Next action</th></tr></thead><tbody>${list.map(r=>{const next=recordAction(r,type);return `<tr><td><div class="company-cell">${companyLogo(r.company)}<span>${recordOpen(r,type,esc(r.company),'table-record-link')}<small>${esc(r.contact)}</small><small>${esc(r.email)}</small></span></div></td><td><span class="lead-table-route">${type==='deal'?esc(r.leadId||'Direct registration'):esc(r.origin==='crm'?salesVendor(r):r.source)}<small>→ ${type==='deal'?'CRM opportunity':r.origin==='crm'?esc(state.company.name):esc(salesVendor(r))}</small></span></td><td>${esc(r.owner||state.user.name)}</td><td><span class="last-activity">${esc(r.history.at(-1)?.title||'Created')}<small>${salesTime(r.updatedAt||r.createdAt)}</small></span></td><td>${type==='deal'?stagePill(r.registration):leadPill(r)}${type==='lead'&&leadIntake(r)?`<small class="table-intake">${esc(leadIntake(r))}</small>`:''}</td>${type==='deal'?`<td>${r.stage?stagePill(r.stage):'<span class="tiny">Not created</span>'}</td>`:''}<td class="numeric amount">${money(r.value)}</td><td>${syncBadge(r)}</td><td>${recordOpen(r,type,esc(next.label||'View details')+' '+icon('arrow'),'text-link')}</td></tr>`}).join('')||`<tr><td colspan="${type==='deal'?9:8}" class="empty">No matching records. Change your search or filter.</td></tr>`}</tbody></table></div></section>`;}
function needsPartnerAction(r,type){const a=recordAction(r,type);return !!a.action&&!['refresh','linked','back-list'].includes(a.action)&&!(type==='deal'&&['Won','Lost'].includes(r.stage));}
// New leads for you: the simple accept flow for leads the vendor sends. Accept, contact, qualify, register.
function leadInbox(leads){
 const live=['Assigned','Accepted','Working','Qualified'],order={Assigned:0,Accepted:1,Working:2,Qualified:3};
 const rows=leads.filter(r=>r.origin==='crm'&&live.includes(r.status)&&workflow.leadStage(r)!=='Converted').sort((a,b)=>order[a.status]-order[b.status]||String(b.assignedAt||b.updatedAt).localeCompare(String(a.assignedAt||a.updatedAt)));
 if(!rows.length)return '';
 const waiting=rows.filter(r=>r.status==='Assigned'&&r.sync?.status!=='pending').length,shown=rows.slice(0,4);
 const steps=['Accept','Contact','Qualify','Register deal'],at={Assigned:0,Accepted:1,Working:2,Qualified:3};
 const first=n=>esc(String(n||'the customer').split(' ')[0]);
 const row=r=>{
  const step=at[r.status],pending=r.sync?.status==='pending',failed=r.sync?.status==='failed',d=workflow.leadDeadline(r);
  const when=d?.kind==='accept'?(d.overdue?'<span class="inbox-due overdue">Response overdue</span>':`<span class="inbox-due">${d.hoursLeft} h left to accept</span>`):d?.kind==='contact'?(d.overdue?'<span class="inbox-due overdue">First contact overdue</span>':`<span class="inbox-due">Contact by ${salesDate(d.due.slice(0,10))}</span>`):'';
  let actions;
  if(pending)actions=state.crm.connected?`<span class="inbox-wait">Syncing…</span>`:`<span class="inbox-wait">Accepted. Sends to Salesforce once connected.</span>${salesButton('Connect Salesforce','connect-salesforce','','',true)}`;
  else if(failed)actions=salesButton('Retry sync','retry','lead',r.id);
  else if(r.status==='Assigned')actions=salesButton('Decline','decline','lead',r.id,true)+salesButton('Accept','inbox-accept','lead',r.id);
  else if(r.status==='Accepted')actions=salesButton('Add details','first-contact','lead',r.id,true)+salesButton('Mark contacted','quick-contact','lead',r.id);
  else if(r.status==='Working')actions=salesButton('Qualify','qualify','lead',r.id);
  else actions=r.dealId?salesButton('Open deal draft','linked','lead',r.id):salesButton('Register deal','register-linked','lead',r.id);
  const next=r.status==='Assigned'?'Sent by '+esc(String(r.receivedFrom||'').replace(/^Vendor · /,'').replace(/^Salesforce$/,'')||'your vendor'):r.status==='Accepted'?'Accepted. Next: reach out to '+first(r.contact)+'.':r.status==='Working'?'In touch with '+first(r.contact)+'. Next: confirm it is a real opportunity.':'Qualified. Register the deal to protect it for 90 days.';
  return `<article class="inbox-row" data-status="${esc(r.status)}"><button type="button" class="inbox-main" data-sales-action="open" data-sales-type="lead" data-sales-id="${esc(r.id)}"><span class="inbox-logo">${esc(String(r.company||'?')[0])}</span><span class="inbox-copy"><b>${esc(r.company)}</b><small>${esc(r.contact)} · ${esc(r.product)} · ${leadCompactMoney(r.value||0)}</small><small class="inbox-next">${next}</small></span></button><ol class="inbox-steps" aria-label="Progress: ${steps[step]}">${steps.map((t,i)=>`<li class="${i<step?'done':i===step?'now':''}"><span></span>${t}</li>`).join('')}</ol><div class="inbox-actions">${pending?'':when}${actions}</div></article>`;
 };
 return `<section class="card lead-inbox" aria-labelledby="inbox-title"><header class="card-header"><div><h3 class="card-title" id="inbox-title">New leads for you${waiting?` <span class="inbox-count">${waiting} to accept</span>`:''}</h3><p class="panel-sub">Your vendor sends you leads. Accept within 48 hours, then reach out within 3 days.</p></div><button type="button" class="btn btn-outline btn-secondary" data-sales-action="source-filter" data-scope="crm">View all</button></header><div class="inbox-list">${shown.map(row).join('')}</div></section>`;
}
function dashboard(){
 const leads=workflow.list('lead'),deals=workflow.list('deal'),open=deals.filter(d=>d.registration==='Approved'&&!['Won','Lost'].includes(d.stage)),won=deals.filter(d=>d.stage==='Won');
 const attention=[...leads.map(r=>({r,type:'lead'})),...deals.map(r=>({r,type:'deal'}))].filter(({r,type})=>needsPartnerAction(r,type)).sort((a,b)=>attentionRank(b)-attentionRank(a));
 const recent=[...leads.map(r=>({r,type:'lead'})),...deals.map(r=>({r,type:'deal'}))].flatMap(({r,type})=>r.history.map(h=>({r,type,h}))).sort((a,b)=>b.h.time.localeCompare(a.h.time)).slice(0,6);
 return `${heading('Your partner workspace.','Every introduction has a clear next step.',salesButton('View Leads','dashboard-filter','','',true).replace('data-sales-action="dashboard-filter"','data-sales-action="dashboard-filter" data-route="leads"')+salesButton('Add New Lead','new-lead')+salesButton('Register Deal','new-deal','','',true))}${leadInbox(leads)}<section class="hero"><div class="hero-copy"><div class="hero-tag">YOUR PARTNER SALES JOURNEY</div><h2>A clear path.<br>More <em>momentum.</em></h2><p>Register a lead. Qualify it. Convert it to a deal.<br>Track each opportunity with Salesforce.</p>${salesButton('How the journey works','help','','',true)}</div><div class="action-dock"><div class="dock-heading"><span class="dock-icon">${icon('bolt')}</span><div><h3>Your next moves</h3><p>One connected workflow, from first contact to outcome.</p></div></div>${task('My Leads',leads.filter(l=>l.origin==='partner').length+' partner-created introductions','leads','my-leads','')}${task('Assigned Leads',leads.filter(l=>l.status==='Assigned').length+' waiting for acceptance','crm','assigned-leads','')}${task('CRM Opportunities',open.length+' open Salesforce opportunities','deals','my-deals','')}</div></section><section class="stats journey-stats">${salesStat('Total Leads',leads.length,'All authorized leads','leads')}${salesStat('New Leads',leads.filter(l=>leadLabel(workflow.leadStage(l))==='New').length,'Review or make first contact','leads','Draft')}${salesStat('Qualified Leads',leads.filter(l=>workflow.leadStage(l)==='Qualified').length,'Ready to register a deal','leads','Qualified')}${salesStat('Active Deals',open.length,money(open.reduce((n,d)=>n+d.value,0))+' in CRM opportunities','opportunities','Active')}${salesStat('Pending Registrations',deals.filter(d=>['Submitted','Pending review'].includes(d.registration)).length,'Awaiting a vendor decision','deals','Pending')}<button class="card stat" data-sales-action="pending-actions"><span class="stat-label">Pending Actions</span><strong class="stat-value">${attention.length}</strong><span class="stat-footer">Your next steps ${icon('arrow')}</span></button></section><section class="card"><header class="card-header"><div><h3 class="card-title">Needs your attention</h3><p class="panel-sub">Actions based on the latest confirmed record status.</p></div>${salesButton(syncBusy?'Syncing…':'Refresh Salesforce','refresh','','',true)}</header><div class="sales-attention-list" id="pending-actions">${(showAllActions?attention:attention.slice(0,5)).map(({r,type})=>recordOpen(r,type,`<span>${companyLogo(r.company)}</span><span class="task-copy"><b>${esc(r.company)}</b><small>${esc(recordAction(r,type).detail)}</small></span><span class="attention-action">${esc(recordAction(r,type).label)} ${icon('arrow')}</span>`,'sales-attention')).join('')||'<p class="empty">You’re all caught up.</p>'}</div>${attention.length>5?salesButton(showAllActions?'Show fewer actions':'View all '+attention.length+' actions','pending-actions','','',true):''}</section><section class="card recent-sales"><header class="card-header"><div><h3 class="card-title">Recent Activities</h3><p class="panel-sub">The latest updates across your leads and deals.</p></div></header>${recent.map(({r,type,h})=>recordOpen(r,type,`<span class="task-symbol">${icon(type==='lead'?'leads':'deals')}</span><span class="task-copy"><b>${esc(h.title)}</b><small>${esc(r.company)} · ${esc(h.actor)}</small></span><time>${salesTime(h.time)}</time>`,'sales-attention')).join('')||'<p class="empty">Your activities will appear here.</p>'}</section>`;
}
// Failed syncs first, then missed lead deadlines.
function attentionRank({r,type}){const deadline=type==='lead'&&workflow.leadDeadline(r);return r.sync.status==='failed'?2:deadline&&deadline.kind!=='protection'&&deadline.overdue?1:0;}
function salesStat(label,value,foot,route,filter='All statuses'){return `<button class="card stat" data-sales-action="dashboard-filter" data-route="${route}" data-filter="${filter}"><span class="stat-label">${label}</span><strong class="stat-value">${value}</strong><span class="stat-footer">${foot}${icon('arrow')}</span></button>`;}
function program(){return `${heading('My program','Your company details and assigned partner benefits.')}<div class="program-workspace"><section class="card form-panel program-company"><div class="panel-head"><h3>${esc(state.company.name)}</h3><span class="program-label">${icon('eye')}View only</span></div><p class="subtitle">${esc(state.company.industry)} · ${esc(state.company.region)}</p><p class="tiny section-note">Program and company access are managed by the vendor. Your role is Partner Manager.</p></section>${programOverview()}</div>`;}
function crm(){
 const pending=state.sales.outbox.filter(o=>o.partnerId===state.sales.partnerId&&['pending','failed'].includes(o.state)&&workflow.list(o.type).some(r=>r.id===o.recordId));
 return `${heading('Salesforce updates','Track your submissions, customer activities, and confirmed sales updates.',salesButton(syncBusy?'Syncing…':'Refresh updates','refresh'))}<section class="card sf-connection"><div class="sf-brand">${salesforceMark()}<div><div class="eyebrow">YOUR PARTNER RECORDS</div><h2>${state.crm.connected?'Connected to your vendor':'Connect when you’re ready'}</h2><p>${state.crm.connected?'Your customer updates go to Salesforce. Lead assignments and decisions return here.':'Keep working in your portal. Connect Salesforce when you want to sync your saved updates.'}</p></div></div><div class="sf-connection-actions">${stagePill(state.crm.connected?'Connected':'Disconnected')}${!state.crm.connected?salesButton('Connect Salesforce','connect-salesforce'):''}</div><div class="sf-meta"><div><span>Partner workspace</span><strong>${esc(state.company.name)}</strong></div><div><span>Last successful sync</span><strong>${state.sales.lastSync?salesTime(state.sales.lastSync):'Not synced yet'}</strong></div><div><span>Your pending updates</span><strong>${pending.length}</strong></div></div></section>${state.sales.lastError?`<div class="sales-error" role="alert">${esc(state.sales.lastError)} ${salesButton('Retry saved updates','retry','','',true)}</div>`:''}<section class="card"><header class="card-header"><div><h3 class="card-title">Your submitted updates</h3><p class="panel-sub">Review what you have sent and resolve any updates waiting for confirmation.</p></div></header><div class="card-body">${pending.map(op=>{const r=getRecord(op.type,op.recordId);return `<div class="queue-row"><div><b>${esc(r.company)}</b><p>${esc(({submitLead:'Lead submission',register:'Deal registration',qualify:'Qualification request',edit:'Customer update',activity:'Customer activity',complete:'Follow-up completion',stage:'Opportunity stage',accept:'Accept assignment',decline:'Decline assignment',close:'Close lead',withdraw:'Withdraw registration',resubmit:'Resubmit lead'})[op.action]||op.action)} · ${op.state==='failed'?esc(op.error):'Waiting to sync'}</p></div>${recordOpen(r,op.type,'View update '+icon('arrow'),'text-link')}</div>`}).join('')||`<p class="subtitle">${state.crm.connected?'All caught up. Your submitted updates are confirmed.':'No queued updates. You can create leads now and connect Salesforce later.'}</p>`}</div></section><p class="tiny section-note">Salesforce is simulated in this preview. Your vendor manages CRM configuration, lead assignments, and registration decisions.</p>`;
}
// A disabled button with a spinner, shown while a submission is sent and the vendor reviews it.
function loadingButton(label,cls){return `<button type="button" class="${cls} is-loading" disabled aria-busy="true"><span class="sales-spinner" aria-hidden="true"></span>${esc(label)}…</button>`;}
function nextPanel(r,type){const next=recordAction(r,type);const op=state.sales.outbox.find(o=>o.id===r.sync.operationId&&['pending','failed'].includes(o.state));return `<p id="sales-action-error" class="field-error" role="alert"></p><section class="sales-next-panel"><div><span class="eyebrow">${r.sync.status==='failed'?'ACTION REQUIRED':'WHAT HAPPENS NEXT'}</span><h3>${esc(next.label||'No action required')}</h3><p>${esc(next.detail)}</p></div>${next.action?salesButton(next.label,next.action,type,r.id):next.loading?loadingButton(next.label,'btn btn-primary'):''}${r.sync.status==='failed'?salesButton('Discard failed update','discard',type,r.id,true):''}${op?`<details class="pending-preview"><summary>View saved update</summary><dl>${Object.entries(op.payload).filter(([key])=>!['id','time','completed'].includes(key)).map(([key,value])=>`<div><dt>${esc(({dueDate:'Follow-up date',jobTitle:'Job title',expectedClose:'Expected close',confirmedNeed:'Customer need confirmed'})[key]||key)}</dt><dd>${esc(typeof value==='boolean'?value?'Confirmed':'Not confirmed':value??'—')}</dd></div>`).join('')||'<p>The current record details are saved for submission to vendor Salesforce.</p>'}</dl></details>`:''}</section>`;}
function salesRecordRows(r,type){
 const permission=workflow.permissions(type,r.id),fieldKeys={'Contact':'contact','Email':'email','Phone':'phone','Website':'website','Industry':'industry','Company size':'employees','Product interest':'product','Estimated value':'value','Customer need':'need','Purchase timeline':'timeline','Lead rating':'rating','Region':'region','Product / service':'product','Quantity':'quantity','Opportunity name':'name','Expected close':'expectedClose'};
 const rows=type==='lead'?[['Contact',r.contact+(r.jobTitle?' · '+r.jobTitle:'')],['Email',r.email],['Phone',r.phone],['Website',r.website],['Industry',r.industry],['Company size',r.employees?r.employees+' employees':''],['Product interest',r.product],['Estimated value',money(r.value)],['Customer need',r.need],['Purchase timeline',r.timeline],['Lead rating',r.rating],['Region',r.region],['Lead source',r.source],['Assigned owner',r.owner||state.user.name],['CRM reference',r.crmId||'Not synced yet'],['Intake status',leadIntake(r)||'Complete'],['Created',salesDate(r.createdAt)]]:[['Registration ID',r.crmId||r.id],['Related lead',r.leadId||'Direct registration'],['Contact',r.contact+(r.jobTitle?' · '+r.jobTitle:'')],['Email',r.email],['Product / service',r.product],['Quantity',r.quantity||'Not specified'],['Opportunity name',r.name],['CRM opportunity',r.opportunityId||'Created after approval'],['Expected close',salesDate(r.expectedClose)],['Submitted',r.submittedAt?salesTime(r.submittedAt):'Not submitted'],['Last updated',salesTime(r.updatedAt)],['Estimated value',money(r.value)],['Customer need',r.need],['Region',r.region],['Created',salesDate(r.createdAt)]];
 return `<section class="crm-record-section"><header class="crm-record-heading"><h3>CUSTOMER RECORD</h3>${syncBadge(r)}</header><div class="crm-record-table">${rows.map(([label,value])=>`<div class="crm-record-row"><div class="crm-record-readonly"><span class="crm-record-label">${label}</span><span class="crm-record-value">${esc(value||'Not added')}</span>${permission.editable&&fieldKeys[label]&&!permission.lockedFields.includes(fieldKeys[label])?`<button type="button" class="crm-record-icon" data-sales-action="edit" data-sales-type="${type}" data-sales-id="${r.id}" aria-label="Edit ${esc(label)}" title="Editable · ${r.crmId?'syncs to CRM':'local draft'}">${icon('edit')}</button>`:`<span class="crm-record-icon" title="Read-only ${r.crmId?'from CRM':'record field'}">${icon('eye')}</span>`}</div></div>`).join('')}</div><div class="crm-record-legend">${r.crmId?'Edits are proposed to Salesforce; confirmed values update after a successful sync.':'Draft values stay on this device until submitted.'}</div></section>`;
}
