function reviewStep(w){
 const v=w.values,chip=field=>SOURCE_CHIP[w.sources[field]]||(v[field]===undefined||v[field]===''?'<span class="extract-chip missing">Add this</span>':'');
 if(!v.name&&v.company&&v.product)v.name=v.company+' · '+v.product;
 const markup=`<div class="form-row">${field('Customer company '+chip('company'),'company',v.company||'')}${select('Customer region '+chip('region'),'region',SalesWorkflow.REGIONS,v.region||'North America')}</div><div class="form-row">${field('Contact name '+chip('contact'),'contact',v.contact||'')}${field('Contact email '+chip('email'),'email',v.email||'','email')}</div><div class="form-row">${field('Job title (optional) '+chip('jobTitle'),'jobTitle',v.jobTitle||'','text',false)}${select('Product '+chip('product'),'product',['',...SalesWorkflow.PRODUCTS],v.product||'')}</div><div class="form-row">${field('Estimated value ($) '+chip('value'),'value',v.value||'','number')}${field('Expected close date '+chip('expectedClose'),'expectedClose',v.expectedClose||'','date')}</div><div class="form-row">${field('Quantity (optional) '+chip('quantity'),'quantity',v.quantity||'','number',false)}${field('Opportunity name '+chip('name'),'name',v.name||'')}</div><div class="field"><label class="form-label" for="deal-need">Customer need ${chip('need')}</label><textarea id="deal-need" class="form-control" name="need" rows="3">${esc(v.need||'')}</textarea></div>`;
 modal('Review the details','Check what was filled in and correct anything that’s wrong.',`<form id="deal-review-form" data-lead-id="${esc(w.leadId||'')}">${wizardSteps(1)}<div class="wizard-return">${salesButton('Back to '+(w.lead?'Leads':'Deals'),'wizard-cancel',w.lead?'lead':'deal',w.lead?.id||'',true)}</div>${w.notes.length?`<div class="banner">${icon('bolt')}<span>${w.notes.map(esc).join(' ')}</span></div>`:''}${lockFields(markup,w.lead?['company','contact','email']:[],{})}${w.story?`<details class="lead-more-details"><summary>Your description</summary><p class="deal-story-quote">${esc(w.story)}</p></details>`:''}<p id="sales-form-error" class="field-error" role="alert"></p><div class="sales-form-actions"><button class="btn btn-outline btn-secondary" type="submit" name="intent" value="back" formnovalidate>Back to Edit</button><button class="btn btn-primary" type="submit" name="intent" value="continue">Continue ${icon('arrow')}</button></div></form>`,true);
 document.getElementById('deal-review-form').onsubmit=e=>{
  e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),intent=e.submitter?.value||'continue';delete form.intent;
  for(const [field,value]of Object.entries(form)){if(String(w.values[field]??'')!==String(value))w.sources[field]='edited';w.values[field]=value;}
  if(intent==='back')return describeStep(w);
  try{workflow.validate({...w.values,value:Number(w.values.value),consent:true,confirmedNeed:true},true);}catch(error){document.getElementById('sales-form-error').textContent=error.message;return;}
  confirmStep(w);
 };
}
function confirmStep(w){
 const v=w.values,rows=[['Customer',v.company],['Contact',v.contact+(v.jobTitle?' · '+v.jobTitle:'')],['Email',v.email],['Region',v.region],['Product',v.product],['Quantity',v.quantity||'Not specified'],['Opportunity',v.name],['Estimated value',money(Number(v.value))],['Expected close',salesDate(v.expectedClose)],['Customer need',v.need],['Lead',w.lead?w.lead.id+' · qualified':'Direct registration']];
 modal('Review & confirm','Submit only when these details are correct. The simulated vendor validates the registration; approval creates or links a CRM opportunity.',`<form id="deal-confirm-form" data-lead-id="${esc(w.leadId||'')}">${wizardSteps(2)}<div class="wizard-return">${salesButton('Back to Deals','wizard-cancel','','',true)}</div><div class="crm-record-table deal-summary">${rows.map(([label,value])=>`<div class="crm-record-row"><div class="crm-record-readonly"><span class="crm-record-label">${label}</span><span class="crm-record-value">${esc(value||'—')}</span><span></span></div></div>`).join('')}</div><label class="sales-checkbox"><input type="checkbox" name="confirmedNeed" ${v.confirmedNeed?'checked':''}>I have discussed and confirmed the customer’s need.</label><label class="sales-checkbox"><input type="checkbox" name="consent" ${v.consent?'checked':''}>I have permission to share these customer details with the vendor.</label><p id="sales-form-error" class="field-error" role="alert"></p><div class="sales-form-actions"><button class="btn btn-outline btn-secondary" type="submit" name="intent" value="back" formnovalidate>Back to Edit</button><button class="btn btn-outline btn-secondary" type="submit" name="intent" value="draft" formnovalidate>Save draft</button><button class="btn btn-primary" type="submit" name="intent" value="submit">Submit Deal Registration ${icon('arrow')}</button></div></form>`,true);
 document.getElementById('deal-confirm-form').onsubmit=e=>{
  e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),intent=e.submitter?.value||'draft';w.values.confirmedNeed=form.confirmedNeed==='on';w.values.consent=form.consent==='on';
  if(intent==='back')return reviewStep(w);
  // A failed submit keeps the draft it created; trying again updates that same draft.
  try{const data={...w.values,value:Number(w.values.value)},record=w.recordId?workflow.edit('deal',w.recordId,data):workflow.createDeal(data,w.leadId);w.recordId=record.id;if(intent==='submit')workflow.submitDeal(record.id);detailRecord={type:'deal',id:record.id};page='deals';refreshSalesUI();toast(record.sync.status==='pending'?'Registration saved for submission. CRM receipt and approval appear in the status timeline.':'Draft saved. Submit it when you’re ready.');if(record.sync.status==='pending')startSalesSync();}catch(error){document.getElementById('sales-form-error').textContent=error.message;}
 };
}
// Warn before a partner registers a customer they already have an open lead for.
function bindDuplicateHint(exceptId){
 const input=document.querySelector('#sales-record-form [name="company"]'),hint=document.getElementById('lead-duplicate-hint');if(!input||!hint)return;
 const keyOf=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const check=()=>{const key=keyOf(input.value),match=key&&workflow.list('lead').find(l=>l.id!==exceptId&&keyOf(l.company)===key&&!['Closed','Rejected','Declined'].includes(l.status));hint.hidden=!match;hint.innerHTML=match?`${icon('help')}<span>You already have a lead for <b>${esc(match.company)}</b> · ${esc(match.id)} · ${esc(leadLabel(workflow.leadStage(match)))}. The vendor rejects duplicate registrations.</span>`:'';};
 input.addEventListener('input',check);check();
}
