 modal('Update opportunity',esc(r.company)+' · Current Salesforce stage: '+esc(r.stage),`<form id="sales-stage-form">${select('Next opportunity stage','stage',[current,...allowed.filter(stage=>stage!==r.stage)],current)}<div id="stage-open-fields">${field('Estimated value ($)','value',r.value,'number',false)}${field('Expected close date','expectedClose',r.expectedClose||'','date',false)}</div><div id="stage-won-fields" hidden>${field('Won amount ($)','wonAmount',r.wonAmount||r.value,'number',false)}${field('Actual close date','closeDate',r.closeDate||new Date().toISOString().slice(0,10),'date',false)}</div><div id="stage-lost-fields" hidden>${select('Lost reason','lostReason',['Select a reason',...SalesWorkflow.LOST_REASONS],r.lostReason||'Select a reason')}</div>${field('Progress / outcome note','reason',r.outcomeReason||'','text',false)}<p class="tiny">Add an outcome note when closing Won or Lost. Confirmed values update after Salesforce sync succeeds.</p><p id="sales-form-error" class="field-error" role="alert"></p><div class="sales-form-actions">${salesButton('Cancel','open','deal',id,true)}<button class="btn btn-primary" type="submit">Send update to Salesforce</button></div></form>`);
