 document.getElementById('sales-stage-form').onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target)),stage=v.stage===current?r.stage:v.stage,details=stage==='Won'?{wonAmount:v.wonAmount,closeDate:v.closeDate}:stage==='Lost'?{lostReason:v.lostReason}:Object.fromEntries(['value','expectedClose'].filter(key=>v[key]!==undefined&&v[key]!=='').map(key=>[key,v[key]]));workflow.updateStage(id,stage,v.reason,details);detailRecord={type:'deal',id};refreshSalesUI();startSalesSync();}catch(error){document.getElementById('sales-form-error').textContent=error.message;}};
