function exportSales(){const type=salesType(),rows=type==='lead'?[['Record ID','Company','Contact','Email','Phone','Origin','Lead stage','Product interest','Rating','Purchase timeline','BANT confirmed','Value','CRM ID'],...scopedRecords(type).map(r=>[r.id,r.company,r.contact,r.email,r.phone||'',r.origin,leadLabel(workflow.leadStage(r)),r.product||'',r.rating||'',r.timeline||'',workflow.bant(r).count+'/4',r.value,r.crmId||''])]:[['Record ID','Company','Contact','Email','Origin','Lead qualification','Registration','Opportunity stage','Value','CRM ID','Opportunity ID'],...scopedRecords(type).map(r=>[r.id,r.company,r.contact,r.email,r.origin||r.leadId||'Direct registration',r.status||'',r.registration||'',r.stage||'',r.value,r.crmId||'',r.opportunityId||''])];const content=rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='prm-'+page+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Authorized records exported.');}
