function journeyHelp(){modal('One journey. Three distinct records.','A lead, a deal registration, and a CRM opportunity mean different things.',`<ol class="sales-help"><li><b>Lead</b><p>A potential customer. Register one you found (your partner account manager approves it if no other partner has), or accept one your vendor assigns within 48 hours. Contact the customer, then qualify the lead with BANT: budget, authority, need, and timeline.</p></li><li><b>Deal registration</b><p>Your request to register a specific opportunity with the vendor: product, value, and expected close date. Describe it in your own words and review the details. Your partner account manager approves it, which protects the deal for 90 days.</p></li><li><b>CRM opportunity</b><p>Created in the vendor’s CRM when the registration is approved. Report Discovery → Proposal → Negotiation → Won, or close it Lost with a reason.</p></li></ol><p class="subtitle">Approval isn’t a win: only the CRM opportunity can be Won or Lost.</p>`);}
function bindForms(){const search=document.getElementById('sales-search');if(search)search.oninput=e=>{salesQuery=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById('sales-search');input?.focus();input?.setSelectionRange(pos,pos);};const filter=document.getElementById('sales-filter');if(filter)filter.onchange=e=>{salesFilter=e.target.value;render();};const sort=document.getElementById('sales-sort');if(sort)sort.onchange=e=>{salesSort=e.target.value;render();};const profile=document.getElementById('profile-form');if(profile)profile.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));state.user={...state.user,name:cleanText(v.name),email:cleanText(v.email)};save();render();toast('Profile saved.');};}
const cleanText=v=>String(v||'').trim();
function handleSalesAction(action,type,id,el={dataset:{}}){
 try{
  if(el.dataset?.card&&id)cardFlow={page};
  else if(cardFlow&&action==='open'){cardFlow=null;return closeModal();}
  if(action==='wizard-cancel'){go(type==='lead'?(getRecord('lead',id).origin==='crm'?'assigned':'leads'):'deals');return;}
  if(action==='pending-actions'){showAllActions=!showAllActions;render();document.getElementById('pending-actions')?.scrollIntoView?.({behavior:'smooth',block:'start'});return;}
  if(action==='source-filter'){leadScope=el.dataset.scope;page=leadScope==='crm'?'assigned':'leads';salesFilter='All statuses';salesQuery='';closeModal();return render();}
  if(action==='dashboard-filter'){leadScope='all';page=el.dataset.route;salesFilter=el.dataset.filter||'All statuses';salesView='list';salesQuery='';closeModal();return render();}
  if(action==='back-list'){const r=getRecord(type,id);go(type==='deal'?'deals':r.origin==='crm'?'assigned':'leads');return;}
  if(action==='opportunity-detail'||action==='registration-detail'){page=action==='opportunity-detail'?'opportunities':'deals';render();return openSalesRecord('deal',id);}
  if(action==='connect-salesforce')return openSetupConnection();
  if(action==='all-drafts'){salesView='list';salesFilter='Draft';state.leadView=salesView;save();return render();}
  if(action==='all-status'&&salesColumns(salesType()).some(col=>col.key===el.dataset.salesStatus)){salesView='list';salesFilter=el.dataset.salesStatus;state.leadView=salesView;save();return render();}
  if(action==='open')return openSalesRecord(type,id);
  if(action==='new-lead')return salesForm('lead');if(action==='new-deal')return dealWizard();
  if(['refresh','retry'].includes(action))return startSalesSync();
  if(action==='help')return journeyHelp();if(action==='export')return exportSales();
  if(action==='notification'){const n=workflow.readNotification(el.dataset.notificationId);page=n.type==='deal'?'deals':getRecord('lead',n.recordId).origin==='crm'?'assigned':'leads';render();return openSalesRecord(n.type,n.recordId);}
  const r=getRecord(type,id);
  if(action==='edit')return type==='deal'?dealWizard(getRecord(type,id).leadId,id):salesForm(type,id);
  if(action==='resubmit')return salesForm(type,id,null,'resubmit');
  if(action==='delete-draft')return deleteDraftModal(type,id);
  if(action==='close-lead')return closeLeadModal(id);
  if(action==='withdraw')return withdrawDealModal(id);
  if(action==='register-linked')return dealWizard(id);
  if(action==='linked'){page='deals';render();return openSalesRecord('deal',r.dealId);}
  if(action==='source-lead'){const lead=getRecord('lead',r.leadId);page=lead.origin==='crm'?'assigned':'leads';render();return openSalesRecord('lead',r.leadId);}
  if(action==='activity')return activityModal(type,id);
  if(action==='first-contact')return activityModal(type,id,'first-contact');
  if(action==='inbox-accept'){workflow.accept(id);detailRecord=null;refreshSalesUI();startSalesSync();return;}
  if(action==='quick-contact'){workflow.addActivity('lead',id,{type:'Call',note:'First contact made. Customer reached.',outcome:'Connected'});detailRecord=null;refreshSalesUI();startSalesSync();return;}
  if(action==='stage')return stageModal(id);
  if(action==='decline')return declineModal(id);
  if(action==='qualify'||action==='bant')return qualifyModal(id);
  if(action==='discard'){workflow.discard(type,id);return refreshSalesUI();}
  if(action==='submit-deal'){cardFlow=null;return confirmStep({leadId:r.leadId,lead:recordOrNull('lead',r.leadId),recordId:r.id,values:{...r},sources:{},notes:[],story:'',locked:{}});}
  if(action==='submit-lead'&&!r.consent)return consentModal(id);
  if(action==='submit-lead')workflow.submitLead(id);
  else if(action==='submit-deal')workflow.submitDeal(id);
  else if(action==='accept')workflow.accept(id);
  else if(action==='complete')workflow.completeActivity(type,id,el.dataset.activityId);
  else return;
  detailRecord={type,id};refreshSalesUI();startSalesSync();
 }catch(error){cardFlow=null;toast(error.message);const area=document.getElementById('sales-action-error');if(area)area.textContent=error.message;}
}
function enhanceTables(){
  document.querySelectorAll('.data-table').forEach(table=>{
    table.parentElement?.setAttribute('tabindex','0');table.parentElement?.setAttribute('role','region');table.parentElement?.setAttribute('aria-label','Scrollable data table');
    table.querySelectorAll('thead th').forEach((th,index)=>{
      let label=th.textContent.trim();if(!label||th.classList.contains('actions-heading'))return;
      th.setAttribute('aria-sort','none');th.innerHTML=`<button aria-label="Sort by ${esc(label)}">${esc(label)}<span class="sort-indicator" aria-hidden="true">↕</span></button>`;
      th.querySelector('button').addEventListener('click',()=>{
        let asc=th.getAttribute('aria-sort')!=='ascending';
        let tbody=table.tBodies[0],rows=[...tbody.rows];if(rows.some(row=>row.cells.length<2))return;
        const value=row=>{let cell=row.cells[index],text=cell.innerText.trim();if(/value|records/i.test(label))return Number(text.replace(/[^0-9.-]/g,''));if(/close/i.test(label))return Date.parse(text);return cell.querySelector('b')?.innerText||text;};
        rows.sort((a,b)=>{let av=value(a),bv=value(b);return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv)))*(asc?1:-1)});
        rows.forEach(row=>tbody.appendChild(row));table.querySelectorAll('th[aria-sort]').forEach(h=>{h.setAttribute('aria-sort','none');h.querySelector('.sort-indicator').textContent='↕'});th.setAttribute('aria-sort',asc?'ascending':'descending');th.querySelector('.sort-indicator').textContent=asc?'↑':'↓';
      });
    });
  });
}

document.addEventListener('click',e=>{
 const el=e.target.closest('[data-sales-action],[data-sales-view],[data-action],[data-page],[data-toggle]');if(!el)return;
 if(el.dataset.salesAction)return handleSalesAction(el.dataset.salesAction,el.dataset.salesType,el.dataset.salesId,el);
 if(el.dataset.salesView){salesView=el.dataset.salesView;state.leadView=salesView;save();return render();}
 if(el.dataset.page)return go(el.dataset.page);
 if(el.dataset.toggle){if(!['mfa','alerts'].includes(el.dataset.toggle))return;state.settings[el.dataset.toggle]=!state.settings[el.dataset.toggle];save();render();return toast('Preference saved.');}
 const action=el.dataset.action;
 if(action==='close')return closeModal();if(action==='sidebar-collapse'){state.sidebarCollapsed=!state.sidebarCollapsed;save();return render();}
 if(action==='menu')return setNavigation(true);if(action==='menu-close')return setNavigation(false);
 if(action==='quick')return startQuick();if(action==='lead')return salesForm('lead');if(action==='register-deal')return dealWizard();
 if(action==='my-leads')return go('leads');if(action==='assigned-leads')return go('assigned');if(action==='my-deals')return go('opportunities');
 if(action==='sync'){closeModal();return startSalesSync();}if(action==='notifications')return notifications();if(action==='search')return searchModal();
 if(action==='support')return journeyHelp();if(action==='logout')return signOut();
});
document.addEventListener('keydown',e=>{
 if(state.signedIn&&state.onboarding===3&&(e.metaKey||e.ctrlKey)){if(e.key==='j'){e.preventDefault();startQuick();}if(e.key==='k'){e.preventDefault();searchModal();}}
 if(e.key==='Escape'){if(document.querySelector('.sidebar.open'))setNavigation(false);else closeModal();}
 if(e.key==='Tab'){const m=document.querySelector('.app-dialog')||document.querySelector('.sidebar.open');if(!m)return;const els=[...m.querySelectorAll('button,input,select,textarea,summary,a[href]')].filter(el=>!el.disabled&&!el.closest('[hidden]'));const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
window.addEventListener('resize',()=>{if(window.innerWidth>800&&document.querySelector('.sidebar.open'))setNavigation(false)});
window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
// Live link with the partner account manager portal: another tab changed the shared simulated Salesforce.
window.addEventListener('storage',e=>{
 if(e.key!=='minute-v1'||!e.newValue)return;
 let fresh;try{fresh=JSON.parse(e.newValue);}catch{return;}
 if(!fresh?.sales)return;
 state.sales=fresh.sales;workflow=connectWorkflow();
 const managerRev=state.sales.crm.managerRev||0,fromManager=managerRev!==seenManagerRev;seenManagerRev=managerRev;
 if(!state.signedIn||state.onboarding!==3)return;
 // A manager decision syncs at once, like a CRM webhook; the partner is told what changed.
 if(fromManager&&state.crm.connected&&!syncBusy){const before=workflow.notifications().length;try{workflow.sync();}catch{}const list=workflow.notifications();if(list.length>before)toast(list[0].title+' · '+list[0].detail);}
 if(document.querySelector('.app-dialog:not(.lead-drawer)'))return;
 refreshSalesUI();
});
save();render();
